export function resolveMdiSvgPath(iconName?: string | null): string {
  if (!iconName) return mdiStoreMarker
  const trimmed = String(iconName).trim()
  if (!trimmed) return mdiStoreMarker
  if (trimmed.startsWith('M') && trimmed.length > 12) return trimmed
  const normalized = trimmed.startsWith('mdi-') ? trimmed : `mdi-${trimmed}`
  return MDI_SVG_PATHS[normalized] || mdiStoreMarker
}

export function renderMdiSvgHtml(iconName?: string | null, size = 18): string {
  const d = resolveMdiSvgPath(iconName)
  return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor" aria-hidden="true" focusable="false" style="display:block"><path d="${d}"/></svg>`
}
